<?php $title='Sonderbericht '.$service->displayNumber($report); ?>
<div class="document-header"><div><strong>WKS · Sonderbericht</strong><div><?= e($report['report_type_name']) ?></div></div><div><strong><?= e($service->displayNumber($report)) ?></strong><div><?= e((new DateTimeImmutable($report['incident_date']))->format('d.m.Y')) ?></div></div></div><?php foreach($service->exportSections($report) as $heading=>$value):?><section class="print-entry"><strong><?= e($heading) ?></strong><?php if(is_array($value)):?><?php foreach($value as $row):?><div class="prose"><?= e(is_array($row)?implode(' | ',$row):$row) ?></div><?php endforeach;?><?php else:?><div class="prose"><?= e($value) ?></div><?php endif;?></section><?php endforeach;?><script>window.addEventListener('load',()=>window.print());</script>
